# Study guides for the Bill of Rights (Art. III) — written for this app.
# Keys: x = plain explanation, k = elements / key points, w = why it exists, t = exam traps,
#       q = self-test, d = digests [{n, c, h (ruling & doctrine), r (why it matters here)}]
NOTES = {
"art-iii-sec-1": {
 "x": "Government may not take away your life, your freedom, or your property unless it follows a fair process and has a fair reason. It also may not treat people differently without a real, relevant basis.\n\nDue process has two sides. Procedural due process asks how the government acted: notice and a chance to be heard before an impartial body. Substantive due process asks whether the law or act itself is fair and reasonable. Equal protection does not require identical treatment. It forbids arbitrary classification.",
 "k": ["Procedural due process: notice, an opportunity to be heard, an impartial tribunal with jurisdiction, and a decision based on evidence.", "Substantive due process: a lawful purpose (public interest) and lawful means (reasonably necessary, not unduly oppressive).", "Valid classification (Cayat test): substantial distinctions; germane to the purpose of the law; not limited to existing conditions only; applies equally to all members of the class.", "The guarantee protects natural and juridical persons, citizens and aliens alike."],
 "w": "It is the master limit on police power: the State may regulate liberty and property for the common good, but only by fair means and for real reasons.",
 "t": ["The Bill of Rights restrains the State, not private persons (People v. Marti).", "Administrative due process does not always require a trial-type hearing; the chance to explain one’s side, even in writing, can suffice.", "Strict scrutiny, intermediate scrutiny and the rational-basis test apply to different classifications. Fundamental rights and suspect classes get strict scrutiny."],
 "q": ["Give the four requisites of a valid classification.", "Distinguish procedural from substantive due process with one example each.", "Does the clause protect a corporation’s property?"],
 "d": [{"n": "People v. Cayat", "c": "68 Phil. 12 (1939)", "h": "A law penalizing members of non-Christian tribes for possessing liquor not native to them was upheld. The Court laid down the four requisites of a reasonable classification: substantial distinctions, germane to the purpose of the law, not limited to existing conditions, and equal application to all members of the class.", "r": "The standard test for equal protection."},
       {"n": "White Light Corporation v. City of Manila", "c": "G.R. No. 122846, January 20, 2009", "h": "A Manila ordinance barring short-time admission and wash-up rates in motels was struck down. Its aim of curbing illicit sex was legitimate, but banning the rates swept in lawful conduct and intruded on liberty and private enterprise. The means were unreasonable and unduly oppressive, so the ordinance failed substantive due process.", "r": "Applies the lawful-purpose / lawful-means test to police-power measures."}]},
"art-iii-sec-2": {
 "x": "You have a right not to be searched, or to have your things or yourself seized, unreasonably. As a rule, the police need a warrant. Only a judge can issue it, and only after personally examining the complainant and witnesses under oath and finding probable cause. The warrant must describe exactly the place to be searched and the persons or things to be seized.",
 "k": ["The right is personal and may be waived, but a waiver must be clear and voluntary.", "Requisites of a valid warrant: (1) probable cause; (2) determined personally by the judge; (3) after examination under oath or affirmation of the complainant and witnesses; (4) particular description of the place, persons or things.", "General warrants are void.", "Evidence obtained in violation of Sec. 2 is inadmissible for any purpose in any proceeding (Sec. 3(2)).", "Recognized warrantless searches: incident to a lawful arrest; plain view; moving vehicles; consented searches; customs searches; stop-and-frisk; exigent and emergency circumstances; checkpoints within limits."],
 "w": "It keeps the power to invade homes and persons under the control of a neutral judge, not the officer who wants the evidence.",
 "t": ["Only a judge, not a prosecutor or administrative officer, may issue search or arrest warrants. The exception is deportation orders by the Commissioner of Immigration to carry out a final order.", "For arrest warrants, the judge may rely on the prosecutor’s report and supporting documents. For search warrants, the judge must personally examine the applicant and witnesses with searching questions.", "A search incident to arrest presupposes a lawful arrest first. It cannot justify the arrest after the fact."],
 "q": ["List the requisites of a valid search warrant.", "Name five recognized warrantless searches.", "Does the exclusionary rule apply to evidence seized by a private individual acting on his own?"],
 "d": [{"n": "Stonehill v. Diokno", "c": "G.R. No. L-19550, June 19, 1967", "h": "Warrants describing the offense only as violations of tax and banking laws and the RPC, and authorizing seizure of practically all business records, were general warrants and void. Evidence seized under them is inadmissible. The Court abandoned the contrary Moncado rule.", "r": "The leading case on the particularity requirement and the exclusionary rule."},
       {"n": "People v. Marti", "c": "G.R. No. 81561, January 18, 1991", "h": "A forwarding company’s proprietor opened a package and found marijuana, then turned it over to agents. The evidence was admissible because the search was by a private person acting on his own, not by the State. The Bill of Rights restrains government.", "r": "Shows that the guarantee applies only to government action."}]},
"art-iii-sec-3": {
 "x": "Your private communications and letters are protected. The government may open or intercept them only with a court order, or when public safety or order requires it as the law prescribes. Anything obtained in violation of this section, or of Section 2, cannot be used as evidence against anyone, in any proceeding.",
 "k": ["Intrusion is allowed only (a) upon lawful order of the court, or (b) when public safety or order requires otherwise, as prescribed by law.", "Paragraph (2) contains the exclusionary rule for Sections 2 and 3: inadmissible “for any purpose in any proceeding.”", "Related statutes: RA 4200 (Anti-Wiretapping), RA 10173 (Data Privacy), RA 9995 (Anti-Photo and Video Voyeurism)."],
 "w": "Privacy of communication protects freedom of thought and association; people speak and write differently when they fear being overheard.",
 "t": ["The constitutional exclusionary rule binds the State. But privacy statutes such as RA 4200 bind private persons too. A recording made secretly by a party to the conversation is still illegal under RA 4200 (Ramirez v. CA).", "Even between spouses, evidence taken by force or stealth from the other spouse’s papers is inadmissible (Zulueta v. CA)."],
 "q": ["When may privacy of communication be intruded upon?", "Is a secret recording by one of the parties to a phone call admissible?"],
 "d": [{"n": "Zulueta v. Court of Appeals", "c": "G.R. No. 107383, February 20, 1996", "h": "A wife forcibly took her husband’s private letters and photos from his clinic to use in legal separation and disbarment cases. The documents were inadmissible. Marriage does not waive a spouse’s right to privacy of communication and correspondence.", "r": "The exclusionary rule applied in a dispute between private parties."},
       {"n": "Ramirez v. Court of Appeals", "c": "G.R. No. 93833, September 28, 1995", "h": "Secretly taping a private conversation without the consent of all parties violates RA 4200, even if the person recording is a party to it. The law makes no distinction.", "r": "Read with Sec. 3: a statute can extend privacy protection to private actors."}]},
"art-iii-sec-4": {
 "x": "The government may not pass laws that cut down your freedom to speak, write, publish or broadcast, or your right to gather peacefully and ask government to fix grievances. Free speech is a preferred right. It is not absolute, but any restriction must clear demanding tests.",
 "k": ["Two aspects: freedom from prior restraint (censorship) and freedom from subsequent punishment.", "Any system of prior restraint carries a heavy presumption of unconstitutionality.", "Content-based restrictions get strict scrutiny and the clear-and-present-danger test. Content-neutral restrictions get intermediate scrutiny (the O’Brien test).", "Unprotected speech includes obscenity, defamation, fighting words, and incitement to imminent lawless action.", "Assembly: permits may regulate time, place and manner but cannot be denied because of the message (BP 880; the maximum-tolerance policy)."],
 "w": "Self-government needs the free flow of ideas; truth is best tested in the open market of ideas.",
 "t": ["Content-neutral regulation is not the same as content-based regulation, and the test changes with it.", "Election-period regulation of speech by private persons on their own property can be unconstitutional (Diocese of Bacolod).", "A public official must prove actual malice to recover for defamation relating to official conduct."],
 "q": ["What is the presumption against prior restraint?", "Distinguish the clear-and-present-danger test from the dangerous-tendency test.", "Give three categories of unprotected speech."],
 "d": [{"n": "Chavez v. Gonzales", "c": "G.R. No. 168338, February 15, 2008", "h": "Official warnings by the DOJ Secretary and the NTC that airing the “Garci” tapes could violate the law and lead to cancelled broadcast permits were struck down as unconstitutional prior restraint. Content-based restraints are presumed invalid and the government bears a heavy burden of justification.", "r": "The leading modern case on prior restraint."},
       {"n": "Diocese of Bacolod v. COMELEC", "c": "G.R. No. 205728, January 21, 2015", "h": "COMELEC could not order a church to remove an oversized tarpaulin about candidates’ RH Law votes, posted on church property. It was the speech of a private citizen on a matter of public concern, not election propaganda by a candidate, and the size limit was a content-based restriction that failed strict scrutiny.", "r": "Applies Sec. 4 to election regulation and private speech."}]},
"art-iii-sec-5": {
 "x": "The government may not set up an official religion, and it may not stop people from practising their faith. No religious test can be required to vote or to hold public office or exercise civil and political rights.",
 "k": ["Two clauses: non-establishment and free exercise.", "Free exercise covers freedom to believe, which is absolute, and freedom to act on belief, which may be regulated.", "Philippine approach: benevolent neutrality and accommodation. A burden on religious exercise needs a compelling state interest pursued by the least restrictive means.", "Related: Art. II, Sec. 6 (separation of Church and State); Art. VI, Sec. 29(2) (no public money for religion)."],
 "w": "It protects conscience and keeps government from taking sides among faiths.",
 "t": ["Benevolent neutrality is not the same as strict separation. Philippine courts may grant exemptions from general laws.", "Religious instruction in public schools is allowed under Art. XIV, Sec. 3(3) on the conditions stated there."],
 "q": ["State the compelling-state-interest test under benevolent neutrality.", "Can students be expelled for refusing to salute the flag on religious grounds?"],
 "d": [{"n": "Estrada v. Escritor", "c": "A.M. No. P-02-1651, August 4, 2003; June 22, 2006", "h": "A court interpreter lived with a man not her husband under a “declaration of pledging faithfulness” approved by her congregation. The Court adopted benevolent neutrality. Since the State showed no compelling interest that the least restrictive means required, she was not held administratively liable for disgraceful and immoral conduct.", "r": "The controlling framework for free-exercise exemptions."},
       {"n": "Ebralinag v. Division Superintendent of Schools of Cebu", "c": "G.R. No. 95770, March 1, 1993", "h": "Expelling Jehovah’s Witness students for refusing to salute the flag and sing the anthem violated free exercise. Their refusal posed no grave and imminent danger to public safety.", "r": "Free exercise prevails absent a grave and present danger."}]},
"art-iii-sec-6": {
 "x": "You may live where you want and move house within the limits the law sets. Only a court order can impair that. You may also travel. That right can be limited only by law and only for national security, public safety or public health.",
 "k": ["Liberty of abode may be impaired only upon lawful order of the court.", "The right to travel may be impaired only by law, on the grounds of national security, public safety or public health.", "Courts may restrict an accused’s travel as a condition of bail, under their inherent power."],
 "w": "Movement is basic to liberty; restrictions must come from the people’s representatives (a law) or a judge, not from executive whim.",
 "t": ["An executive circular alone cannot authorize hold-departure or watchlist orders (Genuino v. De Lima).", "Marcos v. Manglapus upheld a ban on a former president’s return on the basis of the President’s residual powers. It is often treated as sui generis."],
 "q": ["Who may impair liberty of abode? Who may impair the right to travel, and on what grounds?"],
 "d": [{"n": "Genuino v. De Lima", "c": "G.R. No. 197930, April 17, 2018", "h": "DOJ Department Circular No. 41, which allowed the Secretary to issue watchlist and hold-departure orders, was declared unconstitutional. The right to travel may be impaired only by a law on the stated grounds, and no law authorized the DOJ to do so.", "r": "Restrictions on travel need statutory basis."}]},
"art-iii-sec-7": {
 "x": "You have a right to information on matters of public concern. That includes official records, documents on official acts and decisions, and government research data used as a basis for policy, subject to limits set by law.",
 "k": ["Self-executing; enforceable by mandamus.", "Covers matters of public concern and public interest. Some information is exempt: national security, diplomatic negotiations, executive privilege, trade secrets, privacy, matters under investigation and similar categories.", "Related: Art. II, Sec. 28 (full public disclosure policy)."],
 "w": "Citizens cannot hold government accountable for what they cannot see.",
 "t": ["The right is subject to reasonable regulation of the manner of access, but not to denial at the custodian’s discretion.", "Information on negotiations before a final agreement may be protected. The final terms are not (Chavez v. PEA)."],
 "q": ["What remedy enforces the right to information?", "Name four recognized limits."],
 "d": [{"n": "Legaspi v. Civil Service Commission", "c": "G.R. No. L-72119, May 29, 1987", "h": "A citizen may compel the CSC, by mandamus, to disclose whether particular sanitarians passed the civil service exam. The right is self-executing, and any citizen has standing because it is a public right.", "r": "Establishes standing and the mandamus remedy."},
       {"n": "Chavez v. Public Estates Authority", "c": "G.R. No. 133250, July 9, 2002", "h": "The public is entitled to information on negotiations leading to a government contract involving public property, at least at the stage of definite propositions. The Court also voided the transfer of reclaimed submerged lands to a private corporation.", "r": "Scope of “official acts” and the timing of disclosure."}]},
"art-iii-sec-8": {
 "x": "People in both the public and private sectors may form unions, associations or societies for purposes not contrary to law. The government may not cut down this right.",
 "k": ["Purposes must not be contrary to law.", "Government employees may organize (Art. IX-B, Sec. 2(5)), but they have no right to strike.", "Related: Art. XIII, Sec. 3 (rights of workers); the Labor Code on self-organization."],
 "w": "Collective action lets individuals protect interests they could not protect alone.",
 "t": ["The right to form associations does not include a right to strike for government workers."],
 "q": ["Do government employees have the right to strike?"],
 "d": [{"n": "SSS Employees Association v. Court of Appeals", "c": "G.R. No. 85279, July 28, 1989", "h": "Government employees, including those of GOCCs with original charters, may organize but may not strike. Their terms of employment are fixed by law, not by bargaining.", "r": "Defines the limit of the right for public-sector workers."}]},
"art-iii-sec-9": {
 "x": "The government may take private property, but only for public use and only after paying just compensation. That means the full and fair value of the property at the time of taking, paid within a reasonable time.",
 "k": ["Requisites: (1) private property; (2) genuine necessity; (3) taking in the constitutional sense; (4) for public use; (5) payment of just compensation; (6) observance of due process.", "“Taking” includes a substantial burden on use even without transfer of title (e.g., easements that deprive normal use).", "“Public use” is construed broadly as public advantage or benefit.", "Just compensation is a judicial function. Legislative or executive valuations bind the courts only as guides.", "Under RA 10752, initial deposit or payment rules apply before the writ of possession issues."],
 "w": "It balances the State’s inherent power to acquire property against fairness to the owner who bears a public burden.",
 "t": ["Valuation date: generally the time of taking or of filing the complaint, whichever came first.", "Delay in payment may earn legal interest as damages.", "Eminent domain may be delegated to LGUs (by ordinance; LGC Sec. 19) and to public utilities by law."],
 "q": ["List the requisites of a valid exercise of eminent domain.", "When is there “taking” without transfer of title?", "Who finally determines just compensation?"],
 "d": [{"n": "Manosca v. Court of Appeals", "c": "G.R. No. 106440, January 29, 1996", "h": "Expropriating the birthplace of Felix Manalo to preserve it as a national historical landmark was for a public use. That a religious group would incidentally benefit did not defeat the public purpose.", "r": "Public use is understood broadly as public benefit."},
       {"n": "Republic v. Gingoyon", "c": "G.R. No. 166429, December 19, 2005", "h": "In expropriating the NAIA Terminal 3 facilities, the government had to pay the builder the proffered value under RA 8974 before a writ of possession could issue. Rule 67’s mere deposit of assessed value did not suffice.", "r": "Payment rules before possession in infrastructure expropriation."}]},
"art-iii-sec-10": {
 "x": "The legislature may not pass a law that changes the terms of existing contracts to the prejudice of a party. But all contracts are made subject to the State’s police power, so reasonable regulation for the general welfare can still affect them.",
 "k": ["Applies to laws, not judicial decisions or executive acts.", "Impairment means a change in the terms, or new conditions, that lessens a party’s rights.", "Police power prevails: contracts are deemed to incorporate the reserved power of the State to regulate.", "Franchises and licences are generally not contracts protected by this clause (Art. XII, Sec. 11)."],
 "w": "It protects the stability of private bargains while keeping the State able to act for the common good.",
 "t": ["Zoning ordinances may override restrictive covenants in deeds (Ortigas v. Feati Bank)."],
 "q": ["Why do police-power measures that affect contracts not violate this clause?"],
 "d": [{"n": "Ortigas & Co. v. Feati Bank and Trust Co.", "c": "G.R. No. L-24670, December 14, 1979", "h": "A municipal resolution zoning an area as commercial and industrial prevailed over a deed restriction limiting the lots to residential use. Contracts are subject to the police power, so there was no unconstitutional impairment.", "r": "Police power versus non-impairment."}]},
"art-iii-sec-11": {
 "x": "Poverty must not shut anyone out of the courts or quasi-judicial bodies, or deprive them of adequate legal help.",
 "k": ["Basis for exemption of indigent litigants from docket fees (Rules of Court) and for free legal assistance (PAO, IBP).", "Covers access to courts and to quasi-judicial bodies."],
 "w": "Equal justice is meaningless if the poor cannot get into court.",
 "t": ["This right is distinct from the right to counsel of an accused under Secs. 12 and 14."],
 "q": ["What practical rules implement this guarantee?"]},
"art-iii-sec-12": {
 "x": "Once the police are questioning you as a suspect, you have rights. You must be told you may stay silent and may have a lawyer, preferably one you choose. If you cannot afford one, a lawyer must be given to you. You may waive these rights only in writing and with a lawyer present. No torture, force or threats may be used, and no secret detention. A confession obtained in violation of this section cannot be used against you.",
 "k": ["Applies from custodial investigation: when the person is in custody or significantly deprived of freedom, and questioning focuses on him as a suspect (expanded by RA 7438 to include “inviting” a person for questioning).", "Rights: to remain silent; to competent and independent counsel, preferably of his own choice; to be informed of these rights.", "Waiver must be in writing and in the presence of counsel.", "Exclusionary rule: confessions or admissions obtained in violation are inadmissible (par. 3).", "Par. 4: penal and civil sanctions, compensation and rehabilitation for victims of torture and similar practices."],
 "w": "The inherently coercive setting of police custody would otherwise make confessions unreliable and involuntary.",
 "t": ["Rights do not apply to spontaneous statements, or to statements made to private persons or media (absent State involvement).", "A police line-up is generally not custodial investigation.", "“Competent and independent” counsel excludes a lawyer with interests adverse to the accused, such as the police legal officer or a mayor."],
 "q": ["When does custodial investigation begin?", "How may custodial rights be waived?", "Is an extrajudicial confession made to a radio reporter admissible?"],
 "d": [{"n": "People v. Galit", "c": "G.R. No. L-51770, March 20, 1985", "h": "A confession was inadmissible because the accused was not effectively informed of his rights and was not assisted by counsel. A perfunctory recital of rights is not enough; the warnings must be meaningful, in a language the person understands.", "r": "The quality, not just the fact, of the warning matters."}]},
"art-iii-sec-13": {
 "x": "Before conviction, everyone may be released on bail, except those charged with offenses punishable by reclusion perpetua when the evidence of guilt is strong. Bail must not be excessive. Even when the privilege of the writ of habeas corpus is suspended, the right to bail stays.",
 "k": ["Bail is a matter of right before conviction, except in capital offenses or those punishable by reclusion perpetua or life imprisonment when evidence of guilt is strong.", "In such offenses a hearing is mandatory, and the prosecution bears the burden of showing strong evidence.", "Excessive bail is prohibited.", "The right survives suspension of the privilege of the writ."],
 "w": "The presumption of innocence: liberty before judgment is the rule; detention is the exception.",
 "t": ["After conviction by the RTC of an offense not punishable by reclusion perpetua, bail becomes discretionary (Rule 114).", "Bail may be granted in extradition proceedings on clear and convincing proof that the extraditee is not a flight risk (Hong Kong v. Olalia).", "Humanitarian grounds may justify bail even in serious offenses (Enrile v. Sandiganbayan)."],
 "q": ["When is bail a matter of right? A matter of discretion? Not available?", "Is a bail hearing required when the charge carries reclusion perpetua?"],
 "d": [{"n": "Government of Hong Kong SAR v. Olalia", "c": "G.R. No. 153675, April 19, 2007", "h": "A potential extraditee may be admitted to bail. Extradition is not a criminal proceeding, but liberty is still at stake, and international human-rights norms apply. The extraditee must show by clear and convincing evidence that he is not a flight risk.", "r": "Extends the bail guarantee beyond criminal cases."},
       {"n": "Enrile v. Sandiganbayan", "c": "G.R. No. 213847, August 18, 2015", "h": "An accused charged with plunder was granted bail because of his advanced age, frail health and the low risk that he would flee. Bail exists to guarantee appearance, not to punish.", "r": "Bail may rest on humanitarian considerations."}]},
"art-iii-sec-14": {
 "x": "No one may be tried for a crime without due process of law. In every criminal prosecution the accused is presumed innocent until proven guilty. He is entitled to be heard personally and by counsel, to be told the nature of the charge, and to a speedy, impartial and public trial. He may meet the witnesses face to face and compel the attendance of witnesses and evidence in his favor. Trial may continue in his absence after arraignment if he was notified and his failure to appear is unjustifiable.",
 "k": ["Presumption of innocence: guilt must be proved beyond reasonable doubt.", "Right to be heard by himself and counsel.", "Right to be informed of the nature and cause of the accusation (the facts alleged, not the label, control).", "Speedy, impartial and public trial.", "Confrontation and compulsory process.", "Trial in absentia: after arraignment, with due notice and unjustified absence."],
 "w": "It equalizes the contest between the State, with all its resources, and the individual.",
 "t": ["Trial in absentia requires prior arraignment. The accused may still be compelled to appear for identification.", "The description of the acts in the information, not its caption, determines the offense charged."],
 "q": ["List the requisites of trial in absentia.", "What determines the offense charged — the caption or the allegations?"],
 "d": [{"n": "People v. Holgado", "c": "G.R. No. L-2809, March 22, 1950", "h": "Conviction on a plea of guilty entered without counsel, where the court did not inform the accused of his right to a lawyer, violated due process. The case was remanded for proper arraignment and trial.", "r": "The court’s duty to ensure the right to counsel at arraignment."}]},
"art-iii-sec-15": {
 "x": "The privilege of the writ of habeas corpus — the right to have a court look into why someone is detained — may be suspended only for invasion or rebellion, and only when public safety requires it.",
 "k": ["Grounds: invasion or rebellion, when public safety requires it.", "Read with Art. VII, Sec. 18: the President may suspend for up to 60 days; Congress may revoke or extend; the Supreme Court may review the sufficiency of the factual basis within 30 days of a petition.", "Suspension applies only to persons judicially charged with rebellion or offenses inherent in or directly connected with invasion. Anyone arrested must be judicially charged within three days or released."],
 "w": "Habeas corpus is the great writ of liberty; its suspension is an emergency measure with tight limits.",
 "t": ["The writ itself is never suspended — only its privilege.", "The right to bail is not impaired by suspension (Sec. 13)."],
 "q": ["On what grounds may the privilege be suspended, and who may review the basis?"],
 "d": [{"n": "Lansang v. Garcia", "c": "G.R. No. L-33964, December 11, 1971", "h": "The Court may inquire into whether the President’s suspension of the privilege had a sufficient factual basis, abandoning the earlier view that the matter was a political question. Here it found the basis sufficient.", "r": "Judicial review of suspension, now written into Art. VII, Sec. 18."}]},
"art-iii-sec-16": {
 "x": "Everyone has a right to have their case decided promptly — not only in courts, but also before quasi-judicial and administrative bodies.",
 "k": ["Broader than the speedy-trial right of Sec. 14(2): applies to all stages and all bodies, including preliminary investigation.", "Balancing test: length of delay, reasons for it, assertion of the right, and prejudice to the respondent.", "Inordinate delay may warrant dismissal."],
 "w": "Justice delayed burdens respondents with anxiety, expense and lost evidence.",
 "t": ["After Cagang v. Sandiganbayan, the respondent must timely assert the right. Delay is measured against the periods in the rules, and the burden shifts depending on whether those periods were exceeded."],
 "q": ["How does Sec. 16 differ from the speedy-trial right in Sec. 14(2)?", "State the four factors of the balancing test."],
 "d": [{"n": "Cagang v. Sandiganbayan", "c": "G.R. Nos. 206438, 206458 & 210141-42, July 31, 2018", "h": "The Court laid down guidelines for inordinate delay. The case starts with the filing of a formal complaint. Delay is measured against time periods set by rules. If those periods are exceeded, the prosecution must justify the delay. The right must be timely invoked, and it can be waived.", "r": "The governing framework for this section."}]},
"art-iii-sec-17": {
 "x": "No one can be forced to be a witness against himself. The State cannot compel you to give testimony that may incriminate you.",
 "k": ["Covers testimonial compulsion only — compelling a person to communicate facts from his own mind.", "Physical or mechanical acts (fingerprinting, photographs, paraffin tests, physical examination, DNA samples) are generally not covered.", "In a criminal case the accused may refuse to take the stand at all. An ordinary witness must take the stand and may refuse only specific incriminating questions.", "Immunity statutes may remove the privilege by granting immunity."],
 "w": "It protects human dignity and the accusatorial system: the State must prove guilt by its own evidence.",
 "t": ["Being compelled to produce a handwriting specimen has been held testimonial (Beltran v. Samson). A physical examination is not (Villaflor v. Summers).", "The privilege applies in administrative proceedings that are penal in character, such as disbarment or revocation of a licence."],
 "q": ["Is a compelled urine or DNA sample covered?", "May a respondent in a penal administrative case refuse to testify altogether?"],
 "d": [{"n": "Beltran v. Samson", "c": "53 Phil. 570 (1929)", "h": "Compelling the accused to write from dictation to furnish a handwriting specimen violates the privilege. Writing requires the use of the mind; it is not a purely mechanical act.", "r": "The testimonial / physical distinction."},
       {"n": "Villaflor v. Summers", "c": "41 Phil. 62 (1920)", "h": "A woman charged with adultery could be compelled to undergo a physical examination to determine pregnancy. The privilege bars testimonial compulsion, not the use of the body as evidence.", "r": "Physical evidence is outside the privilege."}]},
"art-iii-sec-18": {
 "x": "No one may be detained solely because of his political beliefs and aspirations. Involuntary servitude in any form is prohibited, except as punishment for a crime of which the person has been duly convicted.",
 "k": ["Detention solely for political beliefs is barred. Overt acts may still be punished.", "Involuntary servitude is prohibited, with the exception of punishment for a crime after due conviction.", "Other recognized exceptions in jurisprudence: compulsory military or civil service under law; posse comitatus; return to work orders in labor disputes affecting national interest."],
 "w": "Liberty of conscience and the abolition of forced labor.",
 "t": ["A return-to-work order is not involuntary servitude."],
 "q": ["Give two recognized exceptions to the ban on involuntary servitude."]},
"art-iii-sec-19": {
 "x": "Fines may not be excessive, and cruel, degrading or inhuman punishments may not be imposed. The death penalty may be imposed only for heinous crimes Congress defines for compelling reasons. Any death penalty already imposed was reduced to reclusion perpetua. Physical, psychological or degrading treatment of prisoners, or the use of substandard or inadequate penal facilities, must be dealt with by law.",
 "k": ["Prohibits excessive fines and cruel, degrading or inhuman punishment.", "Death penalty: only for compelling reasons involving heinous crimes, by Congress. RA 9346 (2006) prohibits its imposition.", "Par. (2): law shall deal with the abuse of prisoners and substandard penal facilities."],
 "w": "Punishment must respect human dignity.",
 "t": ["A penalty is not cruel merely because it is severe. It must be flagrantly disproportionate or shocking to the moral sense.", "Under RA 9346, where the law prescribes death, reclusion perpetua (or life imprisonment) is imposed, without eligibility for parole."],
 "q": ["What is the effect of RA 9346 on penalties of death?"]},
"art-iii-sec-20": {
 "x": "No one may be imprisoned for failing to pay a debt or a poll tax.",
 "k": ["“Debt” means a contractual obligation to pay money. It excludes liability arising from crime.", "Poll tax is the community tax (cedula)."],
 "w": "It prevents the revival of imprisonment for debt, a historic abuse against the poor.",
 "t": ["BP 22 (Bouncing Checks Law) does not violate this section. It punishes the act of issuing a worthless check, not the failure to pay a debt (Lozano v. Martinez).", "Estafa involving debts is punishable because of the fraud, not the debt."],
 "q": ["Why is BP 22 not imprisonment for debt?"],
 "d": [{"n": "Lozano v. Martinez", "c": "G.R. No. L-63419, December 18, 1986", "h": "BP 22 was upheld. The gravamen of the offense is the act of making and issuing a worthless check, which harms public interest and the banking system. It is not the non-payment of an obligation.", "r": "Distinguishes penal liability for an act from imprisonment for debt."}]},
"art-iii-sec-21": {
 "x": "No one may be put in jeopardy twice for the same offense. If an act is punished by both a law and an ordinance, a conviction or acquittal under either bars a prosecution under the other for the same act.",
 "k": ["Requisites of first jeopardy: (1) a valid complaint or information; (2) a court of competent jurisdiction; (3) arraignment and plea; (4) conviction, acquittal, or dismissal/termination without the accused’s express consent.", "Second sentence: protection against prosecution for the same act under a law and an ordinance.", "The bar covers the same offense, an attempt or frustration of it, and offenses necessarily included in or including it."],
 "w": "Finality and fairness: the State, with its resources, may not wear down an individual by repeated prosecutions.",
 "t": ["Dismissal on the accused’s own motion generally does not bar re-prosecution — except when the dismissal is on demurrer or for violation of speedy trial, which amounts to an acquittal.", "Doctrine of supervening event: a later charge for a graver offense is allowed if the graver facts arose after the first plea (e.g., the victim dies)."],
 "q": ["List the requisites for the first jeopardy to attach.", "Explain the “same act” rule in the second sentence."],
 "d": [{"n": "People v. Relova", "c": "G.R. No. L-45129, March 6, 1987", "h": "An accused who was charged under a city ordinance for installing electric wiring devices without permit, and whose case was dismissed after arraignment, could not again be charged with theft of electricity under the RPC for the same act. The second sentence of the clause bars it.", "r": "Applies the “same act” rule between an ordinance and a national law."}]},
"art-iii-sec-22": {
 "x": "Congress may not pass an ex post facto law or a bill of attainder.",
 "k": ["Ex post facto law: one that makes criminal an act done before its passage which was innocent when done; aggravates a crime or increases its penalty retroactively; alters the rules of evidence to make conviction easier; or deprives the accused of a defense or protection to which he was entitled.", "It applies only to criminal or penal matters.", "Bill of attainder: a legislative act that inflicts punishment without judicial trial."],
 "w": "People must be able to rely on the law as it stood when they acted; punishment is for courts, not legislatures.",
 "t": ["Procedural laws may apply retroactively if they do not prejudice the accused.", "RPC Art. 22 makes penal laws favorable to the accused retroactive (except for habitual criminals)."],
 "q": ["Give the kinds of ex post facto laws.", "Why was the Anti-Subversion Act not a bill of attainder?"],
 "d": [{"n": "People v. Ferrer", "c": "G.R. Nos. L-32613-14, December 27, 1972", "h": "The Anti-Subversion Act was upheld. It was not a bill of attainder because it did not single out persons for punishment without trial. Guilt still had to be established in court, including knowing and active membership with intent to further the party’s unlawful aims.", "r": "The leading Philippine case on bills of attainder."}]},
}
